function coatStyle(name){return coatSwatches[name]||'#d8e0e4'}
function breedByKey(key){return breedCatalog.find(b=>b.key===key)}
function breedAvatar(breedOrKey,color){const b=typeof breedOrKey==='string'?breedByKey(breedOrKey):breedOrKey;if(!b)return'';if(b.avatarByColor&&color&&Object.prototype.hasOwnProperty.call(b.avatarByColor,color))return b.avatarByColor[color]||'';if(b.avatar)return b.avatar;if(b.avatarByColor){const first=Object.keys(b.avatarByColor)[0];if(first)return b.avatarByColor[first];}return'';}
