async function captureEmailBoard(board,decorMarkup){
  await Promise.all([...board.querySelectorAll('img')].map(img=>img.decode().catch(()=>{})));
  await fitPetPortrait(board.querySelector('.board-dog'));
  await new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)));
  await centerNameInColourBand(board);
  const canvas=document.createElement('canvas');canvas.width=700;canvas.height=798;
  const ctx=canvas.getContext('2d');ctx.scale(2,2);
  const bounds=board.getBoundingClientRect();
  const drawImage=img=>{
    const r=img.getBoundingClientRect(),cs=getComputedStyle(img);
    let width=r.width,height=r.height;
    if(cs.objectFit==='contain'){const k=Math.min(width/img.naturalWidth,height/img.naturalHeight);width=img.naturalWidth*k;height=img.naturalHeight*k;}
    ctx.drawImage(img,r.left-bounds.left+(r.width-width)/2,r.top-bounds.top+(r.height-height)/2,width,height);
  };
  drawImage(board.querySelector('.board-bg'));
  const dog=board.querySelector('.board-dog');if(dog)drawImage(dog);
  let contactGlyphMarkup='';
  for(const el of board.querySelectorAll('.board-nfc,.board-phone-row')){
    const glyph=el.querySelector('.board-contact-text');
    if(glyph){
      const copy=glyph.cloneNode(true),r=glyph.getBoundingClientRect();copy.removeAttribute('class');
      copy.setAttribute('x',String(r.left-bounds.left));copy.setAttribute('y',String(r.top-bounds.top));copy.setAttribute('width',String(r.width));copy.setAttribute('height',String(r.height));
      contactGlyphMarkup+=new XMLSerializer().serializeToString(copy);continue;
    }
    const r=el.getBoundingClientRect(),cs=getComputedStyle(el),fontSize=parseFloat(cs.fontSize),lineHeight=parseFloat(cs.lineHeight)||fontSize*1.2;
    ctx.fillStyle=cs.color;ctx.font=cs.fontWeight+' '+cs.fontSize+' '+cs.fontFamily;ctx.textAlign='center';ctx.textBaseline='alphabetic';
    const lines=el.innerHTML.split(/<br\s*\/?\s*>/i).map(line=>line.replace(/<[^>]*>/g,''));
    const m=ctx.measureText('ABC123'),baseline=(lineHeight-m.actualBoundingBoxAscent-m.actualBoundingBoxDescent)/2+m.actualBoundingBoxAscent;
    lines.forEach((line,index)=>ctx.fillText(line,r.left-bounds.left+r.width/2,r.top-bounds.top+baseline+index*lineHeight));
  }
  const source=board.querySelector('.board-name-svg');let name='';
  if(source){
    if(source.dataset.bandFit!=='inside')throw new Error('名字预览还未完成');
    const clone=source.cloneNode(true),r=source.getBoundingClientRect();clone.removeAttribute('style');clone.removeAttribute('class');
    clone.setAttribute('x',String(r.left-bounds.left));clone.setAttribute('y',String(r.top-bounds.top));clone.setAttribute('width',String(r.width));clone.setAttribute('height',String(r.height));clone.setAttribute('overflow','visible');clone.querySelector('path').setAttribute('fill','none');name=new XMLSerializer().serializeToString(clone);
  }
  const svg='<svg xmlns="http://www.w3.org/2000/svg" width="350" height="399">'+contactGlyphMarkup+name+decorMarkup+'</svg>'; 
  const url=URL.createObjectURL(new Blob([svg],{type:'image/svg+xml'}));
  try{ctx.drawImage(await loadExportImage(url),0,0,350,399);}finally{URL.revokeObjectURL(url);}
  return canvas.toDataURL('image/png');
}
async function prepareEmailPreviews(order){
  if(orderEmailPreviews.has(order.id))return orderEmailPreviews.get(order.id);
  const host=document.createElement('div');host.className='page';host.style.cssText='display:block;position:fixed;left:-10000px;top:0;pointer-events:none';document.body.appendChild(host);
  const live=captureTagDesign(),jobs=[];
  try{
    // Render each design synchronously, then restore the user's working state
    // before waiting for images. Typing in the shipping form stays untouched.
    for(const [index,design] of order.items.entries()){
      applyTagDesign(design);
      for(const side of ['front','back']){
        const board=document.createElement('div');board.className='board';board.id='emailBoard_'+index+'_'+side;board.style.cssText='width:350px!important;height:399px!important';host.appendChild(board);renderBoard(board,side);
        jobs.push({board,decor:productionDecorSvg(side),label:'第 '+(index+1)+' 张 · '+(side==='front'?'正面':'背面'),name:order.id+'-'+(index+1)+'-'+side+'.png'});
      }
    }
  }finally{applyTagDesign(live);}
  try{
    const previews=[];for(const job of jobs)previews.push({name:job.name,label:job.label,data:await captureEmailBoard(job.board,job.decor)});
    orderEmailPreviews.set(order.id,previews);return previews;
  }finally{host.querySelectorAll('.board').forEach(board=>colourBandResize.unobserve(board));host.remove();}
}
async function notifyOrderStage(order,stage,attachments=[]){
  if(PROFILE_PREVIEW_MODE)return {demo:true,customerSent:false,merchantSent:false,previews:[]};
  const previews=await prepareEmailPreviews(order);
  if(order.isDemo||location.protocol==='file:')return {demo:true,customerSent:false,merchantSent:false,previews};
  const isPaypal=order.payMethod==='PayPal';
  if(isPaypal?(!order.paypalOrderId||!order.paypalOrderToken):(!order.airwallexSessionId||!order.airwallexOrderToken))return {ok:false,customerSent:false,merchantSent:false,error:'付款尚未通过服务器核验'};
  try{
    const response=await fetch(isPaypal?PAYPAL_EMAIL_ENDPOINT:AIRWALLEX_EMAIL_ENDPOINT,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({type:stage,sessionId:order.airwallexSessionId,paypalOrderId:order.paypalOrderId,orderToken:isPaypal?order.paypalOrderToken:order.airwallexOrderToken,order,previews,attachments})});
    const result=await response.json().catch(()=>({}));return {...result,ok:response.ok};
  }catch{return {ok:false,customerSent:false,merchantSent:false,error:'订单通知暂未发送，请稍后重试'};}
}
function startPaymentEmail(order){
  const task=notifyOrderStage(order,'payment_received').then(result=>{
    order.customerEmailStatus=result.demo?'演示未发送':result.customerSent?'已发送付款确认':'发送失败';updateStoredOrder(order);
  }).catch(()=>{order.customerEmailStatus='发送失败';updateStoredOrder(order);});
  orderEmailTasks.set(order.id,task);return task;
}

