function normalizeContactFont(value){return Object.prototype.hasOwnProperty.call(TSUN_CONTACT_FONTS,value)?value:'classic';}
function contactLineSvg(value,fontKey,size=36,width=154,lineHeight=size*1.05,ink='currentColor'){
  const key=normalizeContactFont(fontKey),font=TSUN_CONTACT_FONTS[key];
  const chars=Array.from(String(value||'')),spacing=size*.04,strokeUnits=font.units*.018,pad=strokeUnits/2;
  let scale=size/font.units,cursor=0,minX=Infinity,maxX=-Infinity,minY=Infinity,maxY=-Infinity;
  const placed=chars.map((char,index)=>{
    const glyph=font.glyphs[char]||font.glyphs.X,at=cursor;
    if(glyph.d){minX=Math.min(minX,at+(glyph.bounds[0]-pad)*scale);maxX=Math.max(maxX,at+(glyph.bounds[2]+pad)*scale);minY=Math.min(minY,(glyph.bounds[1]-pad)*scale);maxY=Math.max(maxY,(glyph.bounds[3]+pad)*scale);}
    cursor+=glyph.advance*scale+(index<chars.length-1?spacing:0);return {glyph,at};
  });
  const safeWidth=width-12,actualWidth=maxX-minX,fit=Math.min(1,safeWidth/Math.max(1,actualWidth));
  const left=width/2-(minX+maxX)/2*fit,baseline=lineHeight/2+(minY+maxY)/2*fit;
  const n=value=>Number(value.toFixed(4));
  const paths=placed.filter(({glyph})=>glyph.d).map(({glyph,at})=>`<path d="${glyph.d}" transform="translate(${n(left+at*fit)} ${n(baseline)}) scale(${n(scale*fit)} ${n(-scale*fit)})"/>`).join('');
  return `<svg xmlns="http://www.w3.org/2000/svg" class="board-contact-text" data-contact-font="${key}" data-contact-value="${escapeHtml(value)}" viewBox="0 0 ${width} ${lineHeight}" preserveAspectRatio="xMidYMid meet" role="img" aria-label="${escapeHtml(value)}"><title>${escapeHtml(value)}</title><g fill="${escapeHtml(ink)}" stroke="${escapeHtml(ink)}" stroke-width="${strokeUnits}" stroke-linejoin="round">${paths}</g></svg>`;
}
function placedContactLineSvg(value,key,size,y,ink,lineHeight=size*1.05){
  return contactLineSvg(value,key,size,154,lineHeight,ink).replace('class="board-contact-text"',`x="98" y="${y}" width="154" height="${lineHeight}"`);
}
function productionNfcSvg(ink,key=state.contactFont){return placedContactLineSvg('NFC',key,42,399*.34,ink,42*1.2);}
function syncContactFontControls(){
  const group=document.getElementById('contactFontOptions');if(!group)return;
  if(!group.dataset.bound){
    group.dataset.bound='1';
    group.innerHTML=Object.entries(TSUN_CONTACT_FONTS).map(([key,font])=>`<label class="contact-font-card"><input type="radio" name="contactFont" value="${key}" aria-label="${font.label}"><span class="contact-font-title">${font.label}${key==='classic'?'<small>默认</small>':''}</span><span class="contact-font-sample" aria-hidden="true">${contactLineSvg('NFC',key,23,154,29,'#244b5e')}${contactLineSvg('0123',key,29,154,36,'#244b5e')}</span><span class="contact-font-tick" aria-hidden="true">✓</span></label>`).join('');
    group.addEventListener('change',event=>{
      const input=event.target;if(!input.matches('input[name="contactFont"]')||!input.checked)return;
      state.contactFont=normalizeContactFont(input.value);
      // Save this choice with this tag, including after a return from confirmation.
      commitCurrentDesign();renderAll();
    });
  }
  const chosen=normalizeContactFont(state.contactFont);
  group.querySelectorAll('input[name="contactFont"]').forEach(input=>{input.checked=input.value===chosen;input.closest('label').classList.toggle('selected',input.checked);});
}

