function cloneNfcProfile(profile){return {...EMPTY_NFC_PROFILE,...(profile||{})};}
function captureTagDesign(){return {petName:state.petName||'Lucky',contactFont:normalizeContactFont(state.contactFont),ownerPhone:state.ownerPhone||'',ownerCountry:state.ownerCountry||'HK',ownerPhoneInput:state.ownerPhoneInput||'',phoneConfirmation:isPhoneConfirmed()?{...state.phoneConfirmation}:null,ownerName:state.ownerName||'',nfcText:'NFC宠物档案',nfcProfile:cloneNfcProfile(state.nfcProfile),baseVariant:state.baseVariant,baseLabel:(baseVariants[state.baseVariant]||{}).label||state.baseVariant,faceKey:state.faceKey,selectedBreedKey:state.selectedBreedKey||'',breedName:(breedCatalog.find(b=>b.key===state.selectedBreedKey)||{}).name||'',selectedBreedColor:state.selectedBreedColor||'',decorItems:cloneDecorItems(state.decorItems)};}
function applyTagDesign(design){if(!design)return;state.petName=design.petName||'Lucky';state.contactFont=normalizeContactFont(design.contactFont);restoreOwnerPhone(design);state.phoneConfirmation=design.phoneConfirmation?{...design.phoneConfirmation}:null;if(!isPhoneConfirmed())state.phoneConfirmation=null;state.ownerName=design.ownerName||'';state.nfcText='NFC宠物档案';state.nfcProfile=cloneNfcProfile(design.nfcProfile);state.baseVariant=design.baseVariant||'green1';state.faceKey=design.faceKey||'corgi';state.selectedBreedKey=design.selectedBreedKey||'';state.selectedBreedColor=design.selectedBreedColor||'';state.decorItems=cloneDecorItems(design.decorItems);state.selectedDecorId=null;}
function commitCurrentDesign(){const design=captureTagDesign();if(currentCartIndex>=0&&currentCartIndex<cartDesigns.length)cartDesigns[currentCartIndex]=design;else{cartDesigns.push(design);currentCartIndex=cartDesigns.length-1;}return design;}
function resetAdditionalTagDesign(){clearPhoneConfirmation();const petName=state.petName,ownerPhone=state.ownerPhone,ownerName=state.ownerName,nfcProfile=cloneNfcProfile(state.nfcProfile),faceKey=state.faceKey,selectedBreedKey=state.selectedBreedKey,selectedBreedColor=state.selectedBreedColor;state.baseVariant='green1';state.faceKey=faceKey;state.selectedBreedKey=selectedBreedKey;state.selectedBreedColor=selectedBreedColor;state.decorItems={front:[],back:[]};state.selectedDecorId=null;state.activeAccessoryKey='star';state.petName=petName;state.ownerPhone=ownerPhone;state.ownerName=ownerName;state.nfcText='NFC宠物档案';state.nfcProfile=nfcProfile;currentCartIndex=-1;furthestCustomizeStep=0;resetEmptyDecorAdvanceAcknowledgement();}
