      if(!Object.values(candidate).every(Number.isFinite))return;
      img.portraitCandidate=candidate;
      const {left,top,width,height,factor}=fitPortraitAboveBand(candidate,rows,band);
      for(const [p,v] of Object.entries({left:left/350*100+'%',top:top/399*100+'%',width:width/350*100+'%',height:height/399*100+'%',transform:'none',translate:'none'}))img.style.setProperty(p,v,'important');
      img.dataset.portraitClearance='8';img.dataset.portraitScale=factor.toFixed(4);
