  const left=top.findIndex(v=>v>=0),right=W-1-[...top].reverse().findIndex(v=>v>=0);
  const margin=(right-left)*NAME_SAFE_MARGIN;
  // Integrate the whole safe colour band, not just its lowest middle column.
  let area=0,weightedY=0;
  for(let x=Math.ceil(left+margin);x<=right-margin;x++){
    if(top[x]<0||end[x]<top[x])continue;
    const height=end[x]-top[x]+1;
    area+=height;weightedY+=height*(top[x]+end[x])/2;
  }
  const result={top,end,left:left+margin,right:right-margin,cx:(left+right)/2,cy:(top[175]+end[175])/2,visualCy:weightedY/area};
