  clone.removeAttribute('style');clone.removeAttribute('class');
  clone.setAttribute('xmlns','http://www.w3.org/2000/svg');
  clone.setAttribute('viewBox','-50 -40 200 120');
  clone.setAttribute('width','1000');clone.setAttribute('height','600');
  clone.querySelectorAll('path').forEach(path=>path.setAttribute('fill','none'));
  clone.querySelector('text').removeAttribute('transform');
