function renderPaymentCart(){const host=document.getElementById('paymentItemsPreview'),page=document.getElementById('payment');if(!host||!page||!page.classList.contains('active'))return;const designs=cartDesigns.length?cartDesigns:[captureTagDesign()];host.innerHTML=designs.map((design,index)=>`<section class="payment-item-group"><div class="payment-item-head"><b>第 ${index+1} 张狗牌</b><span><span translate="no">${escapeHtml(design.petName||'Lucky')}</span> · ${escapeHtml(design.baseLabel||(baseVariants[design.baseVariant]||{}).label||'已选底板')}</span></div><div class="preview-grid"><div class="preview-card"><span class="label">正面预览</span><div class="board" id="payFront_${index}"></div></div><div class="preview-card"><span class="label">背面预览</span><div class="board" id="payBack_${index}"></div></div></div></section>`).join('');const live=captureTagDesign();designs.forEach((design,index)=>{applyTagDesign(design);renderBoard(document.getElementById('payFront_'+index),'front');renderBoard(document.getElementById('payBack_'+index),'back');});applyTagDesign(live);}
