    const selected=selectedTone.hex===tone.hex,allowed=canSetDecorColour(pos.slot,key,side);
    const label=tone.label;
    return `<button type="button" class="decor-color-btn ${selected?'active':''}" data-decor-color="${key}" data-color-slot="${pos.slot}" data-color-side="${side}" aria-pressed="${selected}" aria-disabled="${!allowed}" aria-label="${label}" title="${allowed?label:decorColourLimitMessage(side)}"><i style="background:${tone.hex}"></i>${tone.label}</button>`;
