// The sample strip previews an accessory; placement stays in the six slots below.
function showAccessoryPreview(trigger,host,side){
  const accessory=accessoryByKey(trigger.dataset.previewAccessory);
  if(!accessory)return;
  document.getElementById('accessoryPreviewDialog')?.close();
  const locked=side==='back'&&!syncBackContactState();
  const dialog=document.createElement('dialog');
  dialog.id='accessoryPreviewDialog';dialog.className='accessory-preview-dialog';
  dialog.setAttribute('aria-labelledby','accessoryPreviewTitle');
  dialog.setAttribute('aria-describedby','accessoryPreviewHint');
  dialog.innerHTML=`<div class="accessory-preview-content">
    <button type="button" class="accessory-preview-close" aria-label="关闭配饰预览">×</button>
    <span class="accessory-preview-side">${side==='front'?'正面配饰':'背面配饰'}</span>
    <div class="accessory-preview-art" aria-hidden="true">${decorAssetIcon(accessory.key)}</div>
    <h3 id="accessoryPreviewTitle">${escapeHtml(accessory.label)}</h3>
    <p id="accessoryPreviewHint">${locked?'请先填写上方的姓名和电话，<br>再到下方 1–6 号位置选择配饰。':'请在下方 1–6 号位置中，<br>选择你喜欢的配饰和颜色。'}</p>
    <button type="button" class="primary accessory-preview-choose" autofocus>${locked?'先填写联系方式 ↑':'去下方选择 ↓'}</button>
  </div>`;
  document.body.append(dialog);
  let followSelection=false;
  dialog.addEventListener('close',()=>{
    dialog.remove();
    if(!followSelection){if(trigger.isConnected)trigger.focus({preventScroll:true});return;}
    if(side==='back'&&!syncBackContactState(true))return;
    const grid=host.querySelector('.front-slot-grid');if(!grid)return;
    const selectors=[...grid.querySelectorAll('select')];
    const select=selectors.find(node=>!node.value)||selectors[0];
    const card=select?.closest('.front-slot-card')||grid;
    card.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'center'});
    select?.focus({preventScroll:true});
    card.classList.add('decor-choice-cue');
    setTimeout(()=>card.classList.remove('decor-choice-cue'),2200);
  },{once:true});
  dialog.querySelector('.accessory-preview-close').addEventListener('click',()=>dialog.close());
  dialog.querySelector('.accessory-preview-choose').addEventListener('click',()=>{followSelection=true;dialog.close();});
  dialog.addEventListener('click',event=>{
    if(event.target!==dialog)return;
    const rect=dialog.getBoundingClientRect();
    if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)dialog.close();
  });
  dialog.showModal();
}

