function renderBaseLibrary(){
  const panel=document.getElementById('panel-base');
  if(!panel||panel.dataset.newBaseLibrary==='1')return;
  const seriesOrder=['松苔绿系列','雾岩灰系列','元气橘系列','蜜桃粉系列','莓果红系列','奶霜白系列','蜜糖黄系列'];
  const seriesTags={'松苔绿系列':'清新治愈','雾岩灰系列':'高级耐看','元气橘系列':'活力可爱','蜜桃粉系列':'甜甜软萌','莓果红系列':'醒目热情','奶霜白系列':'干净百搭','蜜糖黄系列':'明亮元气'};
  const selectedSeries=(baseVariants[state.baseVariant]||{}).series;
  const initialSeries=seriesOrder.includes(selectedSeries)?selectedSeries:seriesOrder[0];
  const cardsFor=series=>Object.entries(baseVariants)
    .filter(([,item])=>item.series===series)
    .sort((a,b)=>Number(Boolean(b[1].recommended))-Number(Boolean(a[1].recommended)))
    .map(([key,item])=>`<button type="button" class="base-card selectable" data-base-variant="${key}" aria-label="选择${item.label}"><span class="base-thumb-wrap"><img loading="lazy" decoding="async" src="${item.front}" alt="${item.label}底板预览"></span>${item.recommended?'<em class="base-recommend">主推</em>':''}<span class="base-card-copy"><b>${item.label}</b><small>${item.description}</small></span></button>`).join('');
  panel.innerHTML='<h3>挑选底板配色</h3><div class="base-series-tip" role="note"><span aria-hidden="true">🐾</span><strong>悄悄告诉你：我们一共有 7 个不同的配色系列哦～每一组都藏着不一样的可爱。主推款已经乖乖排在第一位啦。</strong></div>'+ 
    `<div class="base-color-tabs" role="tablist" aria-label="底板主色系列">${seriesOrder.map(series=>`<button type="button" class="base-color-tab" role="tab" data-base-series-tab="${series}" aria-selected="false">${series.replace('系列','')}</button>`).join('')}</div>`+
    seriesOrder.map(series=>`<section class="base-series" data-base-series-pane="${series}" role="tabpanel" hidden><div class="base-series-head"><b>${series}</b><span>${seriesTags[series]||'人气双拼'}</span></div><div class="base-series-grid">${cardsFor(series)}</div></section>`).join('');
  const activateSeries=series=>{
    panel.closest('.controls').querySelectorAll('[data-base-series-tab]').forEach(tab=>{
      const active=tab.dataset.baseSeriesTab===series;
      tab.classList.toggle('active',active);
      tab.setAttribute('aria-selected',String(active));
    });
    panel.querySelectorAll('[data-base-series-pane]').forEach(pane=>{
      pane.hidden=pane.dataset.baseSeriesPane!==series;
    });
  };
  panel.querySelectorAll('[data-base-series-tab]').forEach(tab=>{
    tab.addEventListener('click',()=>activateSeries(tab.dataset.baseSeriesTab));
  });
  activateSeries(initialSeries);
  panel.dataset.newBaseLibrary='1';
  window.dispatchEvent(new Event('tsun-base-library-ready')); 
}
