function syncNfcBreedFromSelection(){
  const selected=breedByKey(state.selectedBreedKey);
  if(!selected)return;
  state.nfcProfile.breed=TsunI18n.t(selected.name);
  const input=document.getElementById('nfcBreed');
  if(input&&input.value!==state.nfcProfile.breed)input.value=state.nfcProfile.breed;
}
const breedRenderKeys=new WeakMap();
let mobileBreedPage=0,mobileBreedFilter="";
function renderFaceOptions(){
  const host=document.getElementById('breedLibrary');
  if(!host) return;
  const mobile=matchMedia('(max-width:760px)').matches;
  const filterKey=JSON.stringify([state.breedSearch,state.breedCategory]);
  if(filterKey!==mobileBreedFilter){mobileBreedPage=0;mobileBreedFilter=filterKey;}
  const renderKey=JSON.stringify([state.breedSearch,state.breedCategory,state.selectedBreedKey,state.selectedBreedColor,mobile,mobileBreedPage]);
  if(breedRenderKeys.get(host)===renderKey)return;
  const q=(state.breedSearch||'').trim().toLowerCase();
  const filtered=breedCatalog.filter(b=>{
    if(state.breedCategory!=='all'&&b.size!==state.breedCategory) return false;
    if(!q) return true;
    const hay=[b.key.replace(/-/g,' '),b.name,...b.aliases,...b.colors].map(value=>value+' '+TsunI18n.traditional(value)+' '+TsunI18n.english(value)).join(' ').toLowerCase();
    return hay.includes(q);
  });
  const pageCount=Math.max(1,Math.ceil(filtered.length/6));
  mobileBreedPage=Math.min(mobileBreedPage,pageCount-1);
  const shown=mobile?filtered.slice(mobileBreedPage*6,mobileBreedPage*6+6):filtered;
  host.innerHTML=shown.length?shown.map(b=>{
    const selected=state.selectedBreedKey===b.key;
    const previewSrc=breedAvatar(b,selected?state.selectedBreedColor:undefined);
    const colors=b.colors.map(c=>`<button type="button" class="breed-color-btn ${selected&&state.selectedBreedColor===c?'active':''}" data-breed-color="${b.key}|${c}"><span class="coat-dot" style="background:${coatStyle(c)}"></span>${c}</button>`).join('');
    return `<div class="breed-card ${selected?'selected':''}" data-breed-card="${b.key}">${previewSrc?`<div class="breed-avatar-preview" role="button" tabindex="0" aria-label="选择${b.name}，听它叫两声"><img loading="lazy" decoding="async" src="${previewSrc}" alt="${b.name}"></div>`:`<div class="breed-avatar-placeholder">头像<br>待上传</div>`}<div class="breed-info"><div class="breed-name-row"><div class="breed-name">${b.name}</div><span class="breed-size-tag ${b.size}">${b.sizeLabel}</span></div><div class="breed-alias">${b.aliases.length?'别名：'+b.aliases.join(' / '):'&nbsp;'}</div><div class="breed-color-title">选择毛色</div><div class="breed-colors">${colors}</div></div></div>`;
  }).join(''):`<div class="breed-empty">没有找到匹配的犬种，换个关键词试试。</div>`;
  host.querySelectorAll('[data-breed-card]').forEach(card=>card.addEventListener('click',e=>{
    if(e.target.closest('[data-breed-color]')) return;
    const b=breedByKey(card.dataset.breedCard);if(!b)return;
    window.dispatchEvent(new Event('tsun-avatar-selection'));
    state.selectedBreedKey=b.key;
    if(!state.selectedBreedColor||!b.colors.includes(state.selectedBreedColor)) state.selectedBreedColor=b.colors[0]||'';
    syncNfcBreedFromSelection();
    renderAll();
    if(window.tsunPreviewReaction)window.tsunPreviewReaction();else window.tsunPreviewBark?.play(b.key);
  }));
  host.querySelectorAll('.breed-avatar-preview[role=button]').forEach(avatar=>avatar.addEventListener('keydown',e=>{
    if(!['Enter',' '].includes(e.key))return;
    e.preventDefault();if(e.repeat)return;
    const key=avatar.closest('[data-breed-card]').dataset.breedCard;
    avatar.click();
    host.querySelector(`[data-breed-card="${key}"] .breed-avatar-preview`)?.focus({preventScroll:true});
  }));
  host.querySelectorAll('[data-breed-color]').forEach(btn=>btn.addEventListener('click',e=>{
    e.stopPropagation();window.dispatchEvent(new Event('tsun-avatar-selection'));window.tsunPreviewBark?.stop();const [key,color]=btn.dataset.breedColor.split('|');state.selectedBreedKey=key;state.selectedBreedColor=color;syncNfcBreedFromSelection();renderAll();
    if(window.tsunPreviewReaction)window.tsunPreviewReaction();else window.tsunPreviewBark?.play(key);
  }));
  let pager=document.getElementById('breedMobilePager');
  if(!pager){pager=document.createElement('nav');pager.id='breedMobilePager';pager.className='breed-mobile-pager';pager.setAttribute('aria-label','犬种分页');host.after(pager);}
  pager.hidden=!mobile||pageCount<=1;
  pager.innerHTML=`<button type="button" data-page-step="-1" ${mobileBreedPage===0?'disabled':''}>上一页</button><span>第 ${mobileBreedPage+1} / ${pageCount} 页</span><button type="button" data-page-step="1" ${mobileBreedPage===pageCount-1?'disabled':''}>下一页</button>`;
  pager.querySelectorAll('button').forEach(button=>button.addEventListener('click',()=>{mobileBreedPage+=Number(button.dataset.pageStep);renderFaceOptions();document.getElementById('breedSearch').scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth'});}));
  breedRenderKeys.set(host,renderKey);
  const tabs=document.getElementById('breedCategoryTabs');
  if(tabs){
    const defs=[['all','全部',breedCatalog.length],['small','小型犬',breedCatalog.filter(b=>b.size==='small').length],['medium','中型犬',breedCatalog.filter(b=>b.size==='medium').length],['large','大型犬',breedCatalog.filter(b=>b.size==='large').length]];
    tabs.innerHTML=defs.map(([key,label,count])=>`<button type="button" class="breed-category-btn ${state.breedCategory===key?'active':''}" data-breed-category="${key}">${label} · ${count}</button>`).join('');
    tabs.querySelectorAll('[data-breed-category]').forEach(btn=>btn.addEventListener('click',()=>{state.breedCategory=btn.dataset.breedCategory;renderAll();}));
  }
  const search=document.getElementById('breedSearch');
  if(search&&!search.dataset.bound){search.dataset.bound='1';search.value=state.breedSearch;search.addEventListener('input',e=>{state.breedSearch=e.target.value;renderFaceOptions();});}
  const summary=document.getElementById('breedSummary');const boundCount=breedCatalog.filter(b=>!!breedAvatar(b)).length;if(summary)summary.innerHTML=`<span>共 <b>${breedCatalog.length}</b> 个犬种，当前显示 <b>${shown.length}</b> 个</span><span>已绑定 <b>${boundCount}</b> 个犬种头像素材，选择毛色时会优先切换对应头像</span>`;
  const current=document.getElementById('breedCurrent');
  if(current){const b=breedByKey(state.selectedBreedKey);const currentSrc=breedAvatar(b,state.selectedBreedColor);current.innerHTML=b?`<strong>当前选择：${b.name}${state.selectedBreedColor?' · '+state.selectedBreedColor:''}</strong><span>${currentSrc?'已绑定头像素材，可直接用于预览':'头像待上传，后续可直接绑定素材'}</span>`:`<strong>还没有选择犬种</strong><span>请选择犬种和毛色</span>`;}
}
