    renderBoard(board,side);
    await new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)));
    await centerNameInColourBand(board);
    const source=board.querySelector('.board-name-svg');
    svgNode.querySelectorAll('[data-production-name],#productionNameArc,#productionOwnerArc').forEach(node=>node.remove());
    if(!source)return;
