const PRODUCTION_BOARD_TEMPLATE='data:image/webp;base64,';
const productionBoardCache=new Map();
async function productionBoardSource(){
  const key=state.baseVariant,source=boardFrontSrc();
  if(productionBoardCache.has(key))return productionBoardCache.get(key);
  const task=(async()=>{
    // Reuse the supplied high-resolution outline for every colour combination.
    // Sample the selected artwork so exports retain the exact preview colours.
    const [original,template]=await Promise.all([loadExportImage(source),loadExportImage(PRODUCTION_BOARD_TEMPLATE)]);
    const palette=document.createElement('canvas');palette.width=original.naturalWidth;palette.height=original.naturalHeight;
    const paletteContext=palette.getContext('2d',{willReadFrequently:true});paletteContext.drawImage(original,0,0);
    const sample=(x,y)=>Array.from(paletteContext.getImageData(Math.floor(palette.width*x),Math.floor(palette.height*y),1,1).data).slice(0,3);
    const body=sample(.5,.45),band=sample(.5,.94),logo=body.every(channel=>channel>245)?band:[255,255,255];
    const canvas=document.createElement('canvas');canvas.width=template.naturalWidth;canvas.height=template.naturalHeight;
    const context=canvas.getContext('2d',{willReadFrequently:true});context.drawImage(template,0,0);
    const pixels=context.getImageData(0,0,canvas.width,canvas.height),data=pixels.data;
    // Fit the green/red/white mixtures instead of hard thresholds, preserving
    // antialiasing on the logo, colour boundary and transparent outside edge.
    const green=[19-255,174-255,103-255],red=[232-255,56-255,40-255];
    const dot=(a,b)=>a.reduce((sum,value,index)=>sum+value*b[index],0);
    const gg=dot(green,green),rr=dot(red,red),gr=dot(green,red),det=gg*rr-gr*gr;
    for(let i=0;i<data.length;i+=4){
      if(!data[i+3])continue;
      const r=data[i]-255,g=data[i+1]-255,b=data[i+2]-255;
      const pg=r*green[0]+g*green[1]+b*green[2],pr=r*red[0]+g*red[1]+b*red[2];
      const rawBody=(pg*rr-pr*gr)/det,rawBand=(pr*gg-pg*gr)/det;
      const wb=Math.max(0,rawBody),wr=Math.max(0,rawBand),wl=Math.max(0,1-rawBody-rawBand),total=wb+wr+wl;
      for(let channel=0;channel<3;channel++)data[i+channel]=Math.round((wb*body[channel]+wr*band[channel]+wl*logo[channel])/total);
    }
    context.putImageData(pixels,0,0);
    return canvas.toDataURL('image/png');
  })();
  productionBoardCache.set(key,task);
  try{return await task;}catch(error){productionBoardCache.delete(key);throw error;}
}

