async function sendCompletedOrderEmail(order){
  if(PROFILE_PREVIEW_MODE)return {demo:true,customerSent:false,merchantSent:false};
  try{
    await orderEmailTasks.get(order.id);
    const files=await prepareProductionFiles(order);
    const attachments=await Promise.all(Object.values(files).map(async file=>({name:file.name,data:await blobToDataUrl(file.blob)})));
    const delivery=await notifyOrderStage(order,'order_completed',attachments);
    order.productionStatus=delivery.demo?'演示未发送':delivery.merchantSent?'已发送商户':'商户发送失败';
    order.customerEmailStatus=delivery.demo?'演示未发送':delivery.customerSent?'已发送订单及档案':'发送失败';
    updateStoredOrder(order);return delivery;
  }catch(error){
    order.productionStatus='订单通知待重试';updateStoredOrder(order);return {ok:false};
  }
}
