async function startPaypalCheckout(){
  if(!ensureCheckoutProfiles())return;
  if(currentOrder&&!validateOrderPhoneConfirmations(currentOrder.items||[captureTagDesign()]))return;
  if(LOCAL_FILE_REVIEW||PROFILE_PREVIEW_MODE){toast('本地预览不能发起真实付款');return;}
  if(!currentOrder||!validateCustomerEmail())return;
  const button=document.getElementById('paypalPayBtn');
  if(button){button.disabled=true;button.textContent=window.TsunI18n?.locale==='zh-Hant'?'正在開啟 PayPal…':'Opening PayPal…';}
  try{
    currentOrder.customerEmail=state.customerEmail;currentOrder.payMethod='PayPal';currentOrder.status='等待付款';currentOrder.pricing=calculateOrderPricing(currentOrder.items||[]);updateStoredOrder(currentOrder);
    const response=await fetch(PAYPAL_CREATE_ENDPOINT,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({order:currentOrder,locale:window.TsunI18n?.locale==='zh-Hant'?'zh-HK':'en-HK'})});
    const result=await response.json().catch(()=>({}));if(!response.ok||!result.url||!result.id)throw new Error(result.error||'PayPal 暂时无法打开付款页面');
    currentOrder.paypalOrderId=result.id;currentOrder.paypalCheckoutPending=true;updateStoredOrder(currentOrder);
    location.assign(result.url);
  }catch(error){toast(error.message||(window.TsunI18n?.locale==='zh-Hant'?'PayPal 暫時無法使用，請稍後再試。':'PayPal is temporarily unavailable. Please try again.'),9000);if(button){button.disabled=false;renderPaymentOrder(currentOrder);}}
}
async function handlePaypalReturn(){
  if(PROFILE_PREVIEW_MODE)return;
  const params=new URLSearchParams(location.search),result=params.get('paypal_return');
  if(!['success','cancelled'].includes(result)&&params.get('paypal_recover')!=='1')return;
  document.getElementById('tsunEnterGate')?.remove();
  const orderId=params.get('order_id'),order=orderId?loadOrders().find(o=>o.id===orderId):null;
  if(!order){toast('本浏览器找不到该订单，请联系商户核实 PayPal 付款记录',9000);return;}
  currentOrder=order;cartDesigns=order.items||[];currentCartIndex=0;applyTagDesign({...order.items?.[0],nfcProfile:order.nfcProfile});go('checkout');renderPaymentOrder(order);
  if(result==='cancelled'){history.replaceState({},document.title,location.pathname+location.hash);toast('已返回网站，尚未确认付款。请核对 PayPal 付款状态。');return;}
  const paypalId=order.paypalOrderId;
  if(!paypalId||params.get('token')&&params.get('token')!==paypalId){toast('PayPal 付款编号不匹配，请联系客服核实',9000);return;}
  if(order.paymentStatus==='paid'&&order.paypalOrderToken){preparePaidOrderScreen(order);go('orderSuccess');history.replaceState({},document.title,location.pathname+location.hash);return;}
  try{
    toast('正在核实 PayPal 付款…',7000);
    const response=await fetch(PAYPAL_CAPTURE_ENDPOINT,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({orderId:order.id,paypalOrderId:paypalId})});
    const result=await response.json().catch(()=>({}));if(!response.ok||!result.paid||!result.orderToken)throw new Error(result.error||'PayPal 尚未确认付款');
    order.isDemo=result.mode==='sandbox';order.status='已付款';order.paymentStatus='paid';order.payMethod='PayPal';order.paypalOrderToken=result.orderToken;
    order.paypalCheckoutPending=false;order.paymentTransactionId=result.captureId;order.paidAmountCents=result.amountTotal;order.paidAt=new Date().toISOString();order.nfcStatus='等待客户填写';
    updateStoredOrder(order);currentOrder=order;preparePaidOrderScreen(order);if(!state.nfcProfile.breed)syncNfcBreedFromSelection();go('orderSuccess');
    history.replaceState({},document.title,location.pathname+location.hash);openPaymentSuccess();if(!order.isDemo)startPaymentEmail(order);
  }catch(err){go('checkout');renderPaymentOrder(order);toast((err.message||'付款核验失败')+'。若已扣款请勿重复支付，请联系客服核对。',10000);}
}
async function startAirwallexCheckout(){
  if(!ensureCheckoutProfiles())return;
  if(currentOrder&&!validateOrderPhoneConfirmations(currentOrder.items||[captureTagDesign()]))return;
  if(LOCAL_FILE_REVIEW){openLocalPostPaymentPreview();return;}
  if(PROFILE_PREVIEW_MODE){openOriginalProfilePreview();return;}
  if(!currentOrder||!validateCustomerEmail())return;
  const button=document.getElementById('airwallexPayBtn'),recover=document.getElementById('airwallexRecoverBtn');
  const manual=document.getElementById('airwallexManualLink'),status=document.getElementById('airwallexPaymentStatus');
  if(currentOrder.airwallexSessionId&&currentOrder.airwallexPaymentUrl&&currentOrder.paymentStatus!=='paid'){
    if(manual){manual.href=currentOrder.airwallexPaymentUrl;manual.hidden=false;}
    if(recover)recover.hidden=false;
    if(status)status.textContent='An existing payment link is ready. Please check this payment before paying again.';
    return;
  }
  const popup=window.open('about:blank','_blank');
  if(popup){try{popup.opener=null;popup.document.title='Airwallex Payment';}catch{}}
  if(button){button.disabled=true;button.textContent='Opening Airwallex…';}
  try{
    currentOrder.customerEmail=state.customerEmail;currentOrder.payMethod='Airwallex';currentOrder.status='等待付款';
    currentOrder.pricing=calculateOrderPricing(currentOrder.items||[]);updateStoredOrder(currentOrder);
    const response=await fetch(AIRWALLEX_CREATE_ENDPOINT,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({order:currentOrder})});
    const result=await response.json().catch(()=>({}));
    if(!response.ok||!result.url||!result.id)throw new Error(result.error||'Airwallex payment link is not available yet');
    const paymentUrl=new URL(result.url);
    if(paymentUrl.protocol!=='https:'||!(paymentUrl.hostname==='airwallex.com'||paymentUrl.hostname.endsWith('.airwallex.com')))throw new Error('Invalid Airwallex payment URL');
    currentOrder.airwallexSessionId=result.id;currentOrder.airwallexPaymentUrl=paymentUrl.href;
    currentOrder.airwallexCheckoutPending=true;currentOrder.airwallexCheckoutStartedAt=new Date().toISOString();
    updateStoredOrder(currentOrder);
    if(manual){manual.href=paymentUrl.href;manual.hidden=false;}
    if(recover)recover.hidden=false;
    if(status)status.textContent='Pay in the Airwallex tab, then return here and select Check Airwallex Payment to confirm and enter your delivery address.';
    if(popup)popup.location.replace(paymentUrl.href);
    else toast('Browser blocked the payment tab. Use the Airwallex link below.',9000);
  }catch(error){
    if(popup&&!popup.closed)popup.close();
    if(status)status.textContent='Payment link is unavailable. You have not been charged.';
    toast(error.message||'Airwallex 暂时不可用，请稍后再试。',9000);
  }finally{if(button){button.disabled=false;renderPaymentOrder(currentOrder);}}
}
function preparePaidOrderScreen(order){
  document.getElementById('successOrderNumber').textContent='订单号：'+order.id;
  const pageTitle=document.getElementById('orderSuccessTitle'),pageSubtitle=document.getElementById('orderSuccessSubtitle');
  if(pageTitle)pageTitle.textContent='付款成功！';
  if(pageSubtitle)pageSubtitle.textContent='宠物档案资料已保留。请补充快递信息，提交后安排制作和寄送。';
  const shippingForm=document.getElementById('postPaymentShippingForm'),nfcForm=document.getElementById('postPaymentNfcForm'),result=document.getElementById('nfcLinkResult'),complete=document.getElementById('completeOrderBtn');
  if(shippingForm)shippingForm.hidden=false;if(nfcForm)nfcForm.hidden=false;if(result)result.hidden=true;if(complete)complete.hidden=true;
}

async function handleAirwallexReturn(){
  if(PROFILE_PREVIEW_MODE){openOriginalProfilePreview();return;}
  if(new URLSearchParams(location.search).has('paypal_return'))return;
  if(!shouldResumeAirwallexOrder())return;
  const params=new URLSearchParams(location.search),result=params.get('airwallex_return'),orders=loadOrders();
  const orderId=params.get('order_id');
  // Never select an unrelated saved order for payment recovery.
  const order=orderId?orders.find(o=>o.id===orderId):null;
  const enterGate=document.getElementById('tsunEnterGate');if(enterGate)enterGate.remove();
  if(!order){toast('本浏览器没有找到这笔订单，请回到发起付款时使用的设备核对。',9000);return;}
  currentOrder=order;cartDesigns=order.items||[];currentCartIndex=0;applyTagDesign({...order.items?.[0],nfcProfile:order.nfcProfile});go('checkout');renderPaymentOrder(order);
  if(result==='cancelled'){
    history.replaceState({},document.title,location.pathname+location.hash);
    toast('已返回网站，尚未确认付款。请在 Airwallex 后台确认是否扣款。');return;
  }
  if(result!=='success'&&params.get('recover')!=='1')return;
  if(order.status==='已付款'&&order.paymentStatus==='paid'&&order.airwallexOrderToken){preparePaidOrderScreen(order);go('orderSuccess');history.replaceState({},document.title,location.pathname+location.hash);return;}
  const sessionId=order.airwallexSessionId;if(!sessionId){toast('缺少 Airwallex 付款编号，请联系商家确认交易。',9000);return;}
  toast('正在核实 Airwallex 付款状态…',7000);
  try{
    const response=await fetch(AIRWALLEX_CONFIRM_ENDPOINT,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({sessionId,order})});
    const confirmation=await response.json().catch(()=>({}));if(!response.ok||!confirmation.paid||!confirmation.orderToken)throw new Error(confirmation.error||'Airwallex 尚未确认付款');
    order.isDemo=confirmation.mode==='sandbox';order.status='已付款';order.paymentStatus='paid';order.payMethod='Airwallex';order.airwallexOrderToken=confirmation.orderToken;
    order.airwallexSessionId=confirmation.sessionId||sessionId;order.airwallexCheckoutPending=false;order.paymentTransactionId=confirmation.paymentIntentId;
    order.paidAmountCents=confirmation.amountTotal;order.paidAt=new Date().toISOString();order.nfcStatus='等待客户填写';updateStoredOrder(order);
    currentOrder=order;preparePaidOrderScreen(order);if(!state.nfcProfile.breed)syncNfcBreedFromSelection();go('orderSuccess');
    history.replaceState({},document.title,location.pathname+location.hash);openPaymentSuccess();
    if(!order.isDemo)startPaymentEmail(order);
  }catch(error){go('checkout');renderPaymentOrder(order);toast((error.message||'核实付款失败')+'。请不要重复付款，联系客服或刷新后再核对。',9000);}
}
function openLocalPostPaymentPreview(){
  if(!LOCAL_FILE_REVIEW)return;
  enableProfilePreviewMode();
  currentOrder=null;
  openOriginalProfilePreview();
}
function openOriginalProfilePreview(){
  if(!PROFILE_PREVIEW_MODE)return;
  if(!LOCAL_FILE_REVIEW)document.getElementById('tsunEnterGate')?.remove();
  const paymentModal=document.getElementById('paymentSuccessModal');if(paymentModal)paymentModal.hidden=true;
  if(!state.petName)state.petName='Lucky';
  if(!state.nfcProfile.breed)syncNfcBreedFromSelection();
  // Show the existing production forms, with their original markup and styles.
  ['postPaymentShippingForm','postPaymentNfcForm'].forEach(id=>{const el=document.getElementById(id);if(el)el.hidden=false;});
  ['nfcLinkResult','fpsPendingResult','completeOrderBtn'].forEach(id=>{const el=document.getElementById(id);if(el)el.hidden=true;});
  document.getElementById('successOrderNumber').textContent='预览模式 · 无需付款';
  document.getElementById('orderSuccessTitle').textContent='宠物档案预览';
  document.getElementById('orderSuccessSubtitle').textContent='这是付款后的配送资料预览，不会提交正式订单。';
  document.getElementById('submitPostPaymentNfc').textContent='预览宠物档案';
  document.getElementById('customerOrderStatus').textContent='预览资料仅在本页使用，刷新或关闭后不保存。';
  go('orderSuccess');
}
function previewOriginalPetProfile(){
  if(!PROFILE_PREVIEW_MODE)return;
  // An in-memory display object only: no fake paid status, saved order, or slug.
  const preview={id:'PREVIEW',baseVariant:state.baseVariant,petName:state.petName||'Lucky',ownerName:state.ownerName||'',ownerPhone:state.ownerPhone||'',nfcProfile:cloneNfcProfile(state.nfcProfile)};
  openChineseProfile(preview);
}

async function submitPostPaymentNfc(){
  if(PROFILE_PREVIEW_MODE){previewOriginalPetProfile();return;}
  // Allow customers to return, edit and submit the shipping/profile details
  // again after the first completion.
  if(!currentOrder||!['已付款','资料已完善'].includes(currentOrder.status))return;
  if(nfcProfileMissing(state.nfcProfile).length){openNfcDraft(true);validateNfcProfile();return;}
  const required=[
    {name:'收货人姓名',value:state.shipName,el:document.getElementById('shipName')},
    {name:'快递联系电话',value:state.shipPhone,el:document.getElementById('shipPhone')},
    {name:'详细地址',value:state.shipAddress,el:document.getElementById('shipAddress')},
    {name:'主人电话',value:state.ownerPhone,el:document.getElementById('nfcOwnerPhone')},
    {name:'宠物品种',value:state.nfcProfile.breed,el:document.getElementById('nfcBreed')},
    {name:'备用联系人',value:state.nfcProfile.backupOwnerName,el:document.getElementById('nfcBackupOwnerName')},
    {name:'备用联系电话',value:state.nfcProfile.backupPhone,el:document.getElementById('nfcBackupPhone')}
  ];
  const missing=required.filter(item=>!String(item.value||'').trim());
  if(missing.length){toast('请填写：'+missing.map(item=>item.name).join('、'));const first=missing[0].el;if(first){first.scrollIntoView({behavior:'smooth',block:'center'});setTimeout(()=>first.focus(),250);}return;}
  const phoneIssue=currentOwnerPhoneStatus();
  if(!phoneIssue.valid){toast(phoneIssue.message);document.getElementById('nfcOwnerPhone')?.focus();return;}
  const addressIssue=shippingAddressIssue(state.shipAddress);
  if(addressIssue){toast(addressIssue,7000);const addressInput=document.getElementById('shipAddress');if(addressInput){addressInput.scrollIntoView({behavior:'smooth',block:'center'});addressInput.focus({preventScroll:true});}return;}
  const button=document.getElementById('submitPostPaymentNfc');if(button){button.disabled=true;button.textContent='正在提交完整订单…';}
  currentOrder.shipName=state.shipName;currentOrder.shipPhone=state.shipPhone;currentOrder.shipAddress=state.shipAddress;currentOrder.ownerPhone=state.ownerPhone;currentOrder.ownerName=state.ownerName;currentOrder.nfcProfile=cloneNfcProfile(state.nfcProfile);if(currentOrder.items?.[0])currentOrder.items[0].nfcProfile=cloneNfcProfile(state.nfcProfile);currentOrder.nfcStatus='生成中';updateStoredOrder(currentOrder);

  try{
    if(!currentOrder.cloudProfile||currentOrder.profileNeedsReplacement)currentOrder.cloudProfile=await createCloudPetProfile(currentOrder);
    currentOrder.profileNeedsReplacement=false;
    showNfcLinks(currentOrder.cloudProfile);currentOrder.nfcStatus='已生成';updateStoredOrder(currentOrder);
    const form=document.getElementById('postPaymentNfcForm');if(form)form.hidden=true;
  }catch(error){console.error('NFC 档案生成失败',error);currentOrder.nfcStatus='生成失败';updateStoredOrder(currentOrder);toast('订单档案暂时生成失败，请检查网络后重试。');if(button){button.disabled=false;button.textContent='重新提交订单档案';}return;}
  currentOrder.status='资料已完善';updateStoredOrder(currentOrder);
  const shippingForm=document.getElementById('postPaymentShippingForm'),complete=document.getElementById('completeOrderBtn');
  if(shippingForm)shippingForm.hidden=true;if(complete)complete.hidden=false;
  const delivery=await sendCompletedOrderEmail(currentOrder);
  if(button){button.disabled=false;button.textContent='提交快递信息并完成订单档案';}
  toast(delivery.demo?'快递信息和宠物档案已保存。':delivery.customerSent&&delivery.merchantSent?'订单资料及档案邮件已发送。':'资料已保存，邮件通知需要重试。');
}
function bindInputs(){
  const email=document.getElementById('customerEmail');
  if(email&&!email.dataset.bound){email.dataset.bound='1';email.value=state.customerEmail||'';email.addEventListener('input',()=>{state.customerEmail=email.value.trim();if(currentOrder){currentOrder.customerEmail=state.customerEmail;updateStoredOrder(currentOrder);}});}
  const awxButton=document.getElementById('airwallexPayBtn');if(awxButton&&!awxButton.dataset.bound){awxButton.dataset.bound='1';awxButton.addEventListener('click',startAirwallexCheckout);}
  const paypalButton=document.getElementById('paypalPayBtn');if(paypalButton&&!paypalButton.dataset.bound){paypalButton.dataset.bound='1';paypalButton.addEventListener('click',startPaypalCheckout);}
  const paypalRecover=document.getElementById('paypalRecoverBtn');if(paypalRecover&&!paypalRecover.dataset.bound){paypalRecover.dataset.bound='1';paypalRecover.addEventListener('click',()=>{if(currentOrder?.paypalOrderId)location.href='/?paypal_recover=1&order_id='+encodeURIComponent(currentOrder.id);});}
  const awxRecover=document.getElementById('airwallexRecoverBtn');if(awxRecover&&!awxRecover.dataset.bound){awxRecover.dataset.bound='1';awxRecover.addEventListener('click',()=>{if(currentOrder?.airwallexSessionId)location.href='/?recover=1&order_id='+encodeURIComponent(currentOrder.id);});}
  const profileLink=document.getElementById('nfcPublicLink');if(profileLink&&!profileLink.dataset.bound){profileLink.dataset.bound='1';profileLink.addEventListener('click',event=>{if(currentOrder?.cloudProfile){event.preventDefault();openChineseProfile();}});}
  const editProfile=document.getElementById('editNfcProfileBtn');if(editProfile&&!editProfile.dataset.bound){editProfile.dataset.bound='1';editProfile.addEventListener('click',editNfcProfile);}
  const closeDocument=document.getElementById('orderDocumentClose');if(closeDocument&&!closeDocument.dataset.bound){closeDocument.dataset.bound='1';closeDocument.addEventListener('click',()=>document.getElementById('orderDocumentDialog').close());}
  const firstName=document.getElementById('firstName');
  if(firstName&&!firstName.dataset.bound){firstName.dataset.bound='1';firstName.value=state.petName;firstName.addEventListener('input',e=>{const clean=normalizePetName(e.target.value);e.target.value=clean;state.petName=clean;renderAll();});}
  bindOwnerPhoneFields();
  const ownerNameInputs=['ownerName','nfcOwnerName'].map(id=>document.getElementById(id)).filter(Boolean);
  ownerNameInputs.forEach(ownerName=>{
    if(ownerName.dataset.bound)return;
    ownerName.dataset.bound='1';
    ownerName.value=state.ownerName;
    let ownerNameComposing=false;
    const commitOwnerName=target=>{
      const limited=limitOwnerNameValue(target.value);
      state.ownerName=limited;
      ownerNameInputs.forEach(other=>{if(other.value!==limited)other.value=limited;});
      renderAll();
    };
    ownerName.addEventListener('compositionstart',()=>{ownerNameComposing=true;});
    ownerName.addEventListener('compositionend',e=>{ownerNameComposing=false;commitOwnerName(e.target);});
    ownerName.addEventListener('input',e=>{if(ownerNameComposing||e.isComposing)return;commitOwnerName(e.target);});
    ownerName.addEventListener('change',e=>{if(!ownerNameComposing)commitOwnerName(e.target);});
    ownerName.addEventListener('blur',e=>{ownerNameComposing=false;commitOwnerName(e.target);});
  });
  syncNfcBreedFromSelection();
  const nfcBindings={nfcBreed:'breed',nfcBirthDate:'birthDate',nfcCoatMarks:'coatMarks',nfcBackupOwnerName:'backupOwnerName',nfcBackupPhone:'backupPhone',nfcLocation:'location',nfcOwnerMessage:'ownerMessage',nfcDiet:'diet',nfcPersonality:'personality',nfcClinic:'clinic',nfcClinicPhone:'clinicPhone'};
  Object.entries(nfcBindings).forEach(([id,key])=>{const el=document.getElementById(id);if(!el||el.dataset.bound)return;el.dataset.bound='1';el.value=state.nfcProfile[key]||'';el.addEventListener('input',()=>{state.nfcProfile[key]=el.value;});});
  const bindNfcChoiceGroup=(name,key,hiddenId)=>{
    const radios=[...document.querySelectorAll(`input[name="${name}"]`)];
    const hidden=document.getElementById(hiddenId);
    const refresh=()=>radios.forEach(radio=>radio.closest('.nfc-choice')?.classList.toggle('active',radio.checked));
    radios.forEach(radio=>{
      if(radio.dataset.bound)return;
      radio.dataset.bound='1';radio.checked=radio.value===(state.nfcProfile[key]||'');
      radio.addEventListener('change',()=>{if(!radio.checked)return;state.nfcProfile[key]=radio.value;if(hidden)hidden.value=radio.value;refresh();});
    });
    if(hidden)hidden.value=state.nfcProfile[key]||'';refresh();
  };
  bindNfcChoiceGroup('nfcGenderChoice','gender','nfcGender');
  bindNfcChoiceGroup('nfcNeuteredChoice','neutered','nfcNeutered');
  const nfcPhotoInput=document.getElementById('nfcPhotoInput'),nfcPhotoPreview=document.getElementById('nfcPhotoPreview'),nfcPhotoDefault=document.getElementById('nfcPhotoDefault');
  const showNfcPhoto=data=>{if(!nfcPhotoPreview||!nfcPhotoDefault)return;if(data){window.TsunPetFocus?.prepare(data);nfcPhotoPreview.src=data;nfcPhotoPreview.style.display='block';nfcPhotoDefault.style.display='none';}else{nfcPhotoPreview.removeAttribute('src');nfcPhotoPreview.style.display='none';nfcPhotoDefault.style.display='';}};showNfcPhoto(state.nfcProfile.photoData);
  if(nfcPhotoInput&&!nfcPhotoInput.dataset.bound){nfcPhotoInput.dataset.bound='1';nfcPhotoInput.addEventListener('change',()=>queueNfcPhoto(nfcPhotoInput.files?.[0]));}
  const smartAddress=document.getElementById('smartAddress');
  const shipName=document.getElementById('shipName');
  const shipPhone=document.getElementById('shipPhone');
  const shipAddress=document.getElementById('shipAddress');
  if(shipName&&!shipName.dataset.bound){shipName.dataset.bound='1';shipName.value=state.shipName;shipName.addEventListener('input',e=>{state.shipName=e.target.value.trim();});}
  if(shipPhone&&!shipPhone.dataset.bound){shipPhone.dataset.bound='1';shipPhone.value=state.shipPhone;shipPhone.addEventListener('input',e=>{state.shipPhone=normalizeShippingPhone(e.target.value);e.target.value=state.shipPhone;});}
  if(shipAddress&&!shipAddress.dataset.bound){shipAddress.dataset.bound='1';shipAddress.value=state.shipAddress;shipAddress.addEventListener('input',e=>{state.shipAddress=e.target.value.trim();});}
  const applyParsed=()=>{
    if(!smartAddress) return;
    const res=parseShippingBlob(smartAddress.value);
    if(!res.name&&!res.phone&&!res.address){toast('没识别到可用信息，请检查格式后再试。');return;}
    state.shipName=res.name;if(shipName)shipName.value=res.name;
    state.shipPhone=res.phone;if(shipPhone)shipPhone.value=res.phone;
    state.shipAddress=res.address;if(shipAddress)shipAddress.value=res.address;
    toast(res.name&&res.phone?'已识别，请核对信息并补充楼层及室号。':'请核对地址，并补填未识别的姓名或电话。');
  };
  if(smartAddress&&!smartAddress.dataset.bound){smartAddress.dataset.bound='1';smartAddress.addEventListener('paste',()=>setTimeout(applyParsed,60));}
  const parseAddressBtn=document.getElementById('parseAddressBtn');
  if(parseAddressBtn&&!parseAddressBtn.dataset.bound){parseAddressBtn.dataset.bound='1';parseAddressBtn.addEventListener('click',applyParsed);}
  const continueName=document.getElementById('continueName');if(continueName&&!continueName.dataset.bound){continueName.dataset.bound='1';continueName.addEventListener('click',()=>{if(!state.petName.trim()){toast('宠物名字是必填项，填写后才能进入下一页。');return;}if(!/^[A-Za-z0-9\u3400-\u9fff]{1,10}$/.test(state.petName)||petNameUnits(state.petName)>10||petNameChineseCount(state.petName)>4){toast('宠物名字最多 4 个中文字，或 10 个英文字母／数字；混合输入时 1 个中文字按 2 个字符计算，总长度不超过 10 个字符。');return;}cartDesigns=[];currentCartIndex=-1;furthestCustomizeStep=0;resetEmptyDecorAdvanceAcknowledgement();setCustomizeStep('face');go('customize');});}

  const paymentSuccessContinue=document.getElementById('paymentSuccessContinue');if(paymentSuccessContinue&&!paymentSuccessContinue.dataset.bound){paymentSuccessContinue.dataset.bound='1';paymentSuccessContinue.addEventListener('click',continueAfterPayment);}
  const submitPostPaymentNfcBtn=document.getElementById('submitPostPaymentNfc');if(submitPostPaymentNfcBtn&&!submitPostPaymentNfcBtn.dataset.bound){submitPostPaymentNfcBtn.dataset.bound='1';submitPostPaymentNfcBtn.addEventListener('click',submitPostPaymentNfc);}
  const copyPublicLink=document.getElementById('copyPublicLink');if(copyPublicLink&&!copyPublicLink.dataset.bound){copyPublicLink.dataset.bound='1';copyPublicLink.addEventListener('click',copyProfileUrl);}
  const downloadDogBtn=document.getElementById('downloadDogBtn');if(downloadDogBtn&&!downloadDogBtn.dataset.bound){downloadDogBtn.dataset.bound='1';downloadDogBtn.addEventListener('click',()=>downloadProductionFile('dog'));}
  const downloadFrontBtn=document.getElementById('downloadFrontBtn');if(downloadFrontBtn&&!downloadFrontBtn.dataset.bound){downloadFrontBtn.dataset.bound='1';downloadFrontBtn.addEventListener('click',()=>downloadProductionFile('front'));}
  const downloadBackBtn=document.getElementById('downloadBackBtn');if(downloadBackBtn&&!downloadBackBtn.dataset.bound){downloadBackBtn.dataset.bound='1';downloadBackBtn.addEventListener('click',()=>downloadProductionFile('back'));}
  const downloadAllBtn=document.getElementById('downloadAllBtn');if(downloadAllBtn&&!downloadAllBtn.dataset.bound){downloadAllBtn.dataset.bound='1';downloadAllBtn.addEventListener('click',()=>{['front','dog','back'].forEach((kind,index)=>setTimeout(()=>downloadProductionFile(kind),index*250));});}
}
const HOME_FRONT_IMAGE='data:image/webp;base64,';
const HOME_BACK_IMAGE='data:image/webp;base64,';
const HOME_STORY_IMAGE='data:image/webp;base64,';
// Keep the same preview DOM while only the phone or accessories change.
// In particular, never rerun the painted-name fitter for unrelated edits.
const visibleBoardViews=new WeakMap();
const stablePreviewImages=new WeakMap();
function setStablePreviewImage(img,src,alt){
  if(!img)return;
  if(stablePreviewImages.get(img)!==src){img.src=src;stablePreviewImages.set(img,src);}
  if(alt&&img.alt!==alt)img.alt=alt;
}
function renderVisibleBoard(el,side){
  if(!el?.closest('.page.active'))return;
  const home=/^home/.test(el.id);
  const name=side==='back'?(state.ownerName||'').trim():(state.petName||'Lucky');
  const nameKey=JSON.stringify([side,state.baseVariant,name]);
  const layoutKey=home?el.id:JSON.stringify([nameKey,side==='front'?[
    state.selectedBreedKey,state.selectedBreedColor,state.faceKey
  ]:null]);
  const decorKey=JSON.stringify(state.decorItems[side]);
  const contactKey=JSON.stringify([state.ownerPhone,state.ownerCountry,state.contactFont]);
  const previous=visibleBoardViews.get(el);
  const intact=previous&&previous.bg===el.querySelector('.board-bg');
  if(!intact||previous.layoutKey!==layoutKey){
    const nameSvg=intact&&previous.nameKey===nameKey?el.querySelector('.board-name-svg'):null;
    renderBoard(el,side);
    // A different portrait uses the exact same measured name and base geometry.
    const newName=el.querySelector('.board-name-svg');
    if(nameSvg&&newName){newName.replaceWith(nameSvg);queueNameBandCenter(el);}
  }else if(!home){
    if(previous.decorKey!==decorKey){
      renderDecor(el.querySelector('.decor-layer'),side);
      const dog=el.querySelector('.board-dog');
      const reserved=state.decorItems.front.length?'1':'0';
      if(side==='front'&&dog&&dog.dataset.frontDecor!==reserved){
        dog.dataset.frontDecor=reserved;fitPetPortrait(dog);
      }
    }
    if(side==='back'&&previous.contactKey!==contactKey){
      const ink=currentBackInk(),nfc=el.querySelector('.board-nfc'),phone=el.querySelector('.board-phone');
      if(nfc)nfc.innerHTML=contactLineSvg('NFC',state.contactFont,42,154,42*1.2,ink);
      if(phone)phone.innerHTML=phoneLines(state.ownerPhone);
    }
  }
  visibleBoardViews.set(el,{layoutKey,nameKey,decorKey,contactKey,bg:el.querySelector('.board-bg')});
}

function renderAll(){
  const storyOrigin=document.querySelector('.story-side-copy b');if(storyOrigin)storyOrigin.textContent='来自香港 · 尊八八';
  renderBaseLibrary();
  bindBaseOptions();
  normalizeDecorItems();
  renderStaticThumbs();
  // Hidden previews update on page entry; avoid repeated name fitting offscreen.
  const drawVisible=(id,side)=>renderVisibleBoard(document.getElementById(id),side);
  ['homeFront','confirmFront'].forEach(id=>drawVisible(id,'front'));
  ['homeBack','infoBack','confirmBack'].forEach(id=>drawVisible(id,'back'));
  renderPaymentCart();
  setStablePreviewImage(document.querySelector('#homeFront .board-bg'),HOME_FRONT_IMAGE,'首页正面示例图');
  setStablePreviewImage(document.querySelector('#homeBack .board-bg'),HOME_BACK_IMAGE,'首页背面示例图');
  setStablePreviewImage(document.querySelector('.hero-tag'),HOME_FRONT_IMAGE,'首页正面主视觉狗牌');
  setStablePreviewImage(document.querySelector('.story-illustration'),HOME_STORY_IMAGE,'小狗走失后回家的插画');
  const builderSide=currentBuilderSide();
  drawVisible('builderPreview',builderSide);
  const label=document.getElementById('builderPreviewLabel');if(label)label.textContent=builderSide==='front'?'正面预览':'背面预览';
  renderSummary();
  renderDecorCards('front');
  renderDecorCards('back');
  syncOwnerPhoneControls();
  syncContactFontControls();
  syncBackContactState();
  renderDecorEditor();
}
// One set of profile inputs is shared by draft, checkout and paid-order editing.
let nfcEditingPaidOrder=false,nfcPhotoTask=Promise.resolve(),nfcPhotoSequence=0;
const NFC_FIELD_KEYS={nfcBreed:'breed',nfcBirthDate:'birthDate',nfcCoatMarks:'coatMarks',nfcBackupOwnerName:'backupOwnerName',nfcBackupPhone:'backupPhone',nfcLocation:'location',nfcOwnerMessage:'ownerMessage',nfcDiet:'diet',nfcPersonality:'personality',nfcClinic:'clinic',nfcClinicPhone:'clinicPhone'};
function selectedNfcPortrait(design=state){
  const primary=design.items?.[0]||{};
  const key=design.selectedBreedKey||design.breedKey||primary.selectedBreedKey||'';
  const color=design.selectedBreedColor||design.breedColor||primary.selectedBreedColor||'';
  const faceKey=design.faceKey||primary.faceKey||'';
  return breedAvatar(key,color)||(faceOptions.find(face=>face.key===faceKey)||faceOptions[0])?.src||'';
}
// Sample only the selected embedded portrait; reuse its result for both previews.
// Until it is ready, the .64 CSS scale fits the entire source rectangle inside the circle.
const nfcPortraitFitCache=new Map();
function fitNfcCircularPortrait(image){
  if(!image)return Promise.resolve();
  const src=image.getAttribute('src');if(!src)return Promise.resolve();
  image.classList.add('nfc-contained-avatar');
  if(image.nfcPortraitFitSource===src)return image.nfcPortraitFitPromise;
  image.nfcPortraitFitSource=src;
  for(const key of ['scale','x','y'])image.style.removeProperty('--nfc-portrait-'+key);
  if(!nfcPortraitFitCache.has(src))nfcPortraitFitCache.set(src,(async()=>{
    const sample=new Image();sample.src=src;await sample.decode();
    const ratio=Math.min(1,256/Math.max(sample.naturalWidth,sample.naturalHeight));
    const canvas=document.createElement('canvas');
    canvas.width=Math.max(1,Math.round(sample.naturalWidth*ratio));
    canvas.height=Math.max(1,Math.round(sample.naturalHeight*ratio));
    const ctx=canvas.getContext('2d',{willReadFrequently:true});
    ctx.drawImage(sample,0,0,canvas.width,canvas.height);
    const {data}=ctx.getImageData(0,0,canvas.width,canvas.height),w=canvas.width,h=canvas.height;
    let left=w,top=h,right=-1,bottom=-1;
    for(let y=0;y<h;y++)for(let x=0;x<w;x++)if(data[(y*w+x)*4+3]>8){
      left=Math.min(left,x);right=Math.max(right,x);top=Math.min(top,y);bottom=Math.max(bottom,y);
    }
    if(right<left)return {scale:.64,x:0,y:0};
    const cx=(left+right+1)/2,cy=(top+bottom+1)/2;
    let radius=0;
    for(let y=top;y<=bottom;y++)for(let x=left;x<=right;x++)if(data[(y*w+x)*4+3]>8){
      // Include the pixel's corners and a sampling margin, including white fur.
      radius=Math.max(radius,Math.hypot(Math.abs(x+.5-cx)+.5,Math.abs(y+.5-cy)+.5)+1);
    }
    const span=Math.max(w,h),scale=.45*span/Math.max(radius,1);
    return {scale,x:(w/2-cx)/span*scale*100,y:(h/2-cy)/span*scale*100};
  })().catch(()=>({scale:.64,x:0,y:0})));
  image.nfcPortraitFitPromise=nfcPortraitFitCache.get(src).then(fit=>{
    // A previous coat's delayed decode must not overwrite a newer selection.
    if(image.nfcPortraitFitSource!==src||image.getAttribute('src')!==src)return;
    image.style.setProperty('--nfc-portrait-scale',fit.scale.toFixed(6));
    image.style.setProperty('--nfc-portrait-x',fit.x.toFixed(6)+'%');
    image.style.setProperty('--nfc-portrait-y',fit.y.toFixed(6)+'%');
  });
  return image.nfcPortraitFitPromise;
}
function renderNfcSelectedPortrait(){
  const src=selectedNfcPortrait();
  for(const id of ['nfcDraftSelectedAvatar','nfcUploadSelectedAvatar']){
    const image=document.getElementById(id);if(!image)continue;
    if(src&&image.getAttribute('src')!==src)image.src=src;
    fitNfcCircularPortrait(image);
  }
}
// Review receipts are tied to the exact profile contents, so edits require a new preview.
const nfcPreviewReviewed=new Set(),nfcPreviewPhotoIds=new Map();
function nfcPreviewSignature(design=state){
  const p=cloneNfcProfile(design.nfcProfile),photo=p.photoData||'';
  if(photo&&!nfcPreviewPhotoIds.has(photo))nfcPreviewPhotoIds.set(photo,nfcPreviewPhotoIds.size+1);
  p.photoData=photo?nfcPreviewPhotoIds.get(photo):0;
  const breed=breedByKey(design.selectedBreedKey);
  if(breed&&[breed.name,TsunI18n.english(breed.name),TsunI18n.traditional(breed.name)].includes(p.breed))p.breed=breed.key;
  return JSON.stringify([design.petName,design.ownerName,design.ownerPhone,design.baseVariant,design.selectedBreedKey,design.selectedBreedColor,p]);
}
function hasViewedNfcPreview(design=state){return nfcPreviewReviewed.has(nfcPreviewSignature(design));}
function syncNfcPreviewGate(){
  const action=document.getElementById('nfcPreviewAction'),button=document.getElementById('nfcContinueBtn');if(!action||!button)return;
  const ready=hasViewedNfcPreview(),en=TsunI18n.locale==='en';
  action.dataset.reviewed=String(ready);
  document.getElementById('nfcPreviewRequired').textContent=ready?(en?'Preview viewed':'已查看預覽'):(en?'Required preview':'請先查看預覽');
  document.getElementById('nfcPreviewGateNote').textContent=ready?(en?'Preview viewed. You can now continue.':'已查看完整檔案，可以繼續下一步。'):(en?'Open the full preview to check your pet’s profile before continuing. If you edit any details, preview again.':'請先打開完整預覽，查看寶貝的檔案，再繼續下一步。修改資料後，請重新預覽。');
  button.setAttribute('aria-disabled',String(!ready));button.setAttribute('translate','no');
  button.textContent=ready?TsunI18n.t(nfcEditingPaidOrder?'保存并返回配送资料':'下一步：付款'):(en?'Preview first':'先查看預覽');
}
function requestNfcPreview(){
  syncNfcPreviewGate();
  const action=document.getElementById('nfcPreviewAction'),button=action.querySelector('[data-nfc-draft-preview]');
  action.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth',block:'center'});
  button.focus({preventScroll:true});
  toast(TsunI18n.locale==='en'?'Please open the full NFC preview before continuing.':'請先查看完整 NFC 檔案預覽，再繼續下一步。',4500);
}

function nfcDraftOrder(){return {...captureTagDesign(),id:'PREVIEW'};}
function renderNfcDraftCard(){
  renderNfcSelectedPortrait();syncNfcPreviewGate();
  const p=state.nfcProfile,card=document.getElementById('nfcDraftCard');if(!card)return;
  TsunProfileTheme.apply(card,state.baseVariant);
  const photo=document.getElementById('nfcDraftPhoto'),fallback=document.getElementById('nfcDraftFallback');
  if(p.photoData){if(photo.getAttribute('src')!==p.photoData)photo.src=p.photoData;photo.hidden=false;fallback.hidden=true;}
  else{photo.hidden=true;photo.removeAttribute('src');fallback.hidden=false;}
  document.getElementById('nfcDraftName').textContent=state.petName||'LUCKY';
  document.getElementById('nfcDraftBreed').textContent=p.breed||'';
  document.getElementById('nfcDraftLocation').textContent=p.location||'';
  document.getElementById('nfcDraftMessage').textContent=p.ownerMessage||'';
  document.getElementById('nfcDraftPhone').textContent=inspectOwnerPhone(state.ownerPhone,state.ownerCountry).international||state.ownerPhone||'';
}
function hydrateNfcInputs(){
  if(!state.nfcProfile.breed)syncNfcBreedFromSelection();
  for(const [id,key]of Object.entries(NFC_FIELD_KEYS)){const el=document.getElementById(id);if(el)el.value=state.nfcProfile[key]||'';}
  window.TsunBirthDate?.sync();
  document.getElementById('nfcOwnerName').value=state.ownerName||'';syncOwnerPhoneControls();
  for(const [name,key,id]of [['nfcGenderChoice','gender','nfcGender'],['nfcNeuteredChoice','neutered','nfcNeutered']]){
    document.getElementById(id).value=state.nfcProfile[key]||'';
    document.querySelectorAll(`input[name="${name}"]`).forEach(r=>{r.checked=r.value===state.nfcProfile[key];r.closest('.nfc-choice')?.classList.toggle('active',r.checked);});
  }
  const image=document.getElementById('nfcPhotoPreview'),fallback=document.getElementById('nfcPhotoDefault');
  if(state.nfcProfile.photoData){image.src=state.nfcProfile.photoData;image.style.display='block';fallback.style.display='none';}
  else{image.removeAttribute('src');image.style.display='none';fallback.style.display='';}
  if(!state.nfcProfile.photoData)document.getElementById('nfcPhotoInput').value='';
  document.getElementById('nfcPhotoStatus').textContent=state.nfcProfile.photoData?'宠物照片已加入 NFC 档案':'';
  Object.keys(NFC_FIELD_KEYS).forEach(id=>document.getElementById(id)?.removeAttribute('aria-invalid'));
  document.getElementById('postPaymentNfcForm').hidden=false;
  const select=document.getElementById('nfcTagSelect'),wrap=document.getElementById('nfcTagSelectField');
  wrap.hidden=nfcEditingPaidOrder||cartDesigns.length<2;
  select.replaceChildren(...cartDesigns.map((design,i)=>new Option(`${i+1} · ${design.petName}`,String(i))));select.value=String(currentCartIndex);
  document.getElementById('nfcContinueBtn').textContent=nfcEditingPaidOrder?'保存并返回配送资料':'下一步：付款';
  document.getElementById('nfcDraftBack').textContent=nfcEditingPaidOrder?'返回配送资料':'返回正反面预览';
  renderNfcDraftCard();
}
function nfcProfileMissing(profile){return [['nfcBreed','宠物品种',profile?.breed],['nfcBackupOwnerName','备用联系人',profile?.backupOwnerName],['nfcBackupPhone','备用联系电话',profile?.backupPhone]].filter(([, ,v])=>!String(v||'').trim());}
function validateNfcProfile(){
  const missing=nfcProfileMissing(state.nfcProfile);
  Object.keys(NFC_FIELD_KEYS).forEach(id=>document.getElementById(id)?.setAttribute('aria-invalid',String(missing.some(([field])=>field===id))));
  if(!missing.length)return true;
  toast('请填写：'+missing.map(([,label])=>TsunI18n.t(label)).join(', '),5000);
  const field=document.getElementById(missing[0][0]);field.scrollIntoView({behavior:'smooth',block:'center'});field.focus({preventScroll:true});return false;
}
function openNfcDraft(paid=false){
  nfcEditingPaidOrder=paid;
  if(paid&&currentOrder){
    applyTagDesign({...currentOrder.items?.[0],petName:currentOrder.petName,ownerName:currentOrder.ownerName,ownerPhone:currentOrder.ownerPhone,nfcProfile:currentOrder.nfcProfile});
  }
  go('petProfile');
}
function ensureCheckoutProfiles(){
  const items=currentOrder?.items||cartDesigns;
  const index=items.findIndex(item=>nfcProfileMissing(item.nfcProfile).length);
  if(index<0)return true;
  cartDesigns=items.map(item=>({...item,nfcProfile:cloneNfcProfile(item.nfcProfile),decorItems:cloneDecorItems(item.decorItems)}));currentCartIndex=index;applyTagDesign(cartDesigns[index]);openNfcDraft();validateNfcProfile();return false;
}
async function finishNfcDraft(){
  const button=document.getElementById('nfcContinueBtn');button.disabled=true;
  try{
    await nfcPhotoTask;
    if(!validateNfcProfile())return;
    if(!hasViewedNfcPreview()){requestNfcPreview();return;}
    if(nfcEditingPaidOrder&&currentOrder){
      currentOrder.nfcProfile=cloneNfcProfile(state.nfcProfile);
      if(currentOrder.items?.[0])currentOrder.items[0].nfcProfile=cloneNfcProfile(state.nfcProfile);
      currentOrder.profileNeedsReplacement=!!currentOrder.cloudProfile;updateStoredOrder(currentOrder);
      if(['资料已完善'].includes(currentOrder.status))currentOrder.status='已付款';
      updateStoredOrder(currentOrder);preparePaidOrderScreen(currentOrder);go('orderSuccess');return;
    }
    commitCurrentDesign();
    const missing=cartDesigns.findIndex(item=>nfcProfileMissing(item.nfcProfile).length);
    if(missing>=0){currentCartIndex=missing;applyTagDesign(cartDesigns[missing]);hydrateNfcInputs();validateNfcProfile();return;}
    const unreviewed=cartDesigns.findIndex(item=>!hasViewedNfcPreview(item));
    if(unreviewed>=0){currentCartIndex=unreviewed;applyTagDesign(cartDesigns[unreviewed]);hydrateNfcInputs();requestNfcPreview();return;}
    if(!validateOrderPhoneConfirmations(cartDesigns))return;
    const reusable=currentOrder&&['待付款','等待付款'].includes(currentOrder.status)?currentOrder:null;
    currentOrder=createOrderFromState(reusable);currentOrder.nfcPreparedBeforePayment=true;updateStoredOrder(currentOrder);
    go('checkout');renderPaymentOrder(currentOrder);
  }catch(error){console.error('NFC draft could not be saved',error);toast('资料未能保存，请稍后重试。',5000);}
  finally{button.disabled=false;syncNfcPreviewGate();}
}
function renderPaidProfileSummary(){
  const p=currentOrder?.nfcProfile||state.nfcProfile;
  document.getElementById('paidNfcName').textContent=currentOrder?.petName||state.petName||'LUCKY';
  document.getElementById('paidNfcSummaryText').textContent=nfcProfileMissing(p).length?'请先补充宠物资料，再提交配送信息。':'宠物资料和照片已保留，只需填写配送信息。';
}
function queueNfcPhoto(file){
  const sequence=++nfcPhotoSequence;if(!file)return;
  const button=document.getElementById('nfcContinueBtn');button.disabled=true;
  document.getElementById('nfcPhotoStatus').textContent='正在处理照片…';
  nfcPhotoTask=new Promise((resolve,reject)=>{
    if(!file.type.startsWith('image/'))return reject(new Error('请选择图片文件。'));
    if(file.size>20*1024*1024)return reject(new Error('请选择小于 20MB 的照片。'));
    const reader=new FileReader();reader.onerror=()=>reject(new Error('照片读取失败，请重试。'));
    reader.onload=()=>{const image=new Image();image.onerror=()=>reject(new Error('这张图片无法读取，请换一张。'));image.onload=()=>{
      try{const scale=Math.min(1,700/Math.max(image.naturalWidth,image.naturalHeight)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.naturalWidth*scale));canvas.height=Math.max(1,Math.round(image.naturalHeight*scale));const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(image,0,0,canvas.width,canvas.height);resolve(canvas.toDataURL('image/jpeg',.8));}catch(e){reject(e);}
    };image.src=reader.result;};reader.readAsDataURL(file);
  }).then(data=>{
    if(sequence!==nfcPhotoSequence)return;state.nfcProfile.photoData=data;
    const image=document.getElementById('nfcPhotoPreview');image.src=data;image.style.display='block';document.getElementById('nfcPhotoDefault').style.display='none';
    document.getElementById('nfcPhotoStatus').textContent='宠物照片已加入 NFC 档案';renderNfcDraftCard();
  }).catch(error=>{if(sequence===nfcPhotoSequence){document.getElementById('nfcPhotoStatus').textContent=error.message;toast(error.message,5000);}})
    .finally(()=>{if(sequence===nfcPhotoSequence)button.disabled=false;});
}
function bindNfcDraftFlow(){
  document.getElementById('reviewToNfc').addEventListener('click',()=>openNfcDraft());
  document.getElementById('nfcContinueBtn').addEventListener('click',finishNfcDraft);
  document.getElementById('nfcDraftBack').addEventListener('click',async()=>{await nfcPhotoTask;if(nfcEditingPaidOrder){go('orderSuccess');return;}commitCurrentDesign();go('confirm');renderPaymentOrder(currentOrder);});
  document.getElementById('nfcTagSelect').addEventListener('change',async e=>{const index=Number(e.target.value);await nfcPhotoTask;commitCurrentDesign();currentCartIndex=index;applyTagDesign(cartDesigns[index]);document.getElementById('nfcPhotoInput').value='';hydrateNfcInputs();});
  document.querySelectorAll('[data-nfc-draft-preview]').forEach(button=>button.addEventListener('click',async()=>{
    await nfcPhotoTask;const signature=nfcPreviewSignature();openChineseProfile(nfcDraftOrder());
    if(document.getElementById('orderDocumentDialog').open){nfcPreviewReviewed.add(signature);syncNfcPreviewGate();}
  }));
  document.getElementById('postPaymentNfcForm').addEventListener('input',event=>{if(event.target.value?.trim())event.target.removeAttribute('aria-invalid');renderNfcDraftCard();});
  document.getElementById('postPaymentNfcForm').addEventListener('change',renderNfcDraftCard);
  document.getElementById('editPaidNfc').addEventListener('click',()=>openNfcDraft(true));
  window.addEventListener('tsun-language-change',()=>{renderNfcDraftCard();});
}

try{
  renderStaticThumbs();
  bindInputs();
  bindNfcDraftFlow();
  updateCustomizeNav();
  renderAll();
  // PayPal uses server-side Orders API; no browser SDK availability check is needed.
}catch(error){
  console.error('页面初始化失败，继续恢复付款订单',error);
}finally{
  // Payment recovery is more important than optional page rendering. Even if
  // a thumbnail or decorative widget fails, a paid customer can continue.
  handleAirwallexReturn();
  handlePaypalReturn();
}
